/* eslint-disable max-len */

'use strict';

// MODULES //

var tape = require( 'tape' );
var proxyquire = require( 'proxyquire' );
var discreteUniform = require( '@stdlib/random/base/discrete-uniform' );
var Float64Array = require( '@stdlib/array/float64' );
var dgemm = require( '@stdlib/blas/base/dgemm' );
var isSameValue = require( '@stdlib/assert/is-same-value' );
var floor = require( '@stdlib/math/base/special/floor' );
var sqrt = require( '@stdlib/math/base/special/sqrt' );
var pow = require( '@stdlib/math/base/special/pow' );
var abs = require( '@stdlib/math/base/special/abs' );
var max = require( '@stdlib/math/base/special/max' );
var min = require( '@stdlib/math/base/special/min' );
var defaults = require( './../lib/defaults.js' );
var winograd = require( './../lib/winograd.js' );
var depth = require( './../lib/depth.js' );
var createMatrix = require( './fixtures/create_matrix.js' );
var firstDifference = require( './fixtures/first_difference.js' );


// VARIABLES //

var SEED = 20261030;
var TRIALS = 2000;
var MAX_DIM = 80;
var ALPHAS = [ 0.0, 1.0, -1.0, 2.0, 0.5, -3.0 ];
var NONZERO_ALPHAS = [ 1.0, -1.0, 2.0, 0.5, -3.0 ];
var BETAS = [ 0.0, 1.0, -1.0, 2.0, 0.5 ];
var CUTOFFS = [ 1, 2, 3, 5, 8, 16 ];
var LEVELS = [ 1, 2, 3, 100 ];
var TRANS = [ 'no-transpose', 'transpose' ];
var ORDERS = [ 'row-major', 'column-major' ];

// Exactness budget in units of the common dyadic grid: `2^52` for the term `α*op(A)*op(B)` (including every Strassen–Winograd intermediate) and `2^52` for the term `β*C`, such that no exact value exceeds `2^53`:
var HALF_BUDGET = pow( 2.0, 52 );

// Largest magnitude of random integer entries in `A` and `B`:
var MAX_MAGNITUDE = pow( 2.0, 26 );

// Number of invocations of the Strassen–Winograd kernel by `base.js` (updated by a spy):
var ncalls = 0;

var base = proxyquire( './../lib/base.js', {
	'./winograd.js': spy
});

// Public interfaces (default cutoff and levels) whose kernel invocations are recorded by the spy:
var blas = proxyquire( './../lib/dgemmsw.js', {
	'./base.js': base
});
var ndarray = proxyquire( './../lib/ndarray.js', {
	'./base.js': base
});


// FUNCTIONS //

/**
* Invokes the Strassen–Winograd kernel and records the invocation.
*
* @private
* @returns {Float64Array} output matrix
*/
function spy() {
	ncalls += 1;
	return winograd.apply( null, arguments );
}

/**
* Returns the largest integer magnitude for the entries of `A` and `B` such that every intermediate value is exact.
*
* ## Notes
*
* -   With integer entries bounded by `R`, every intermediate value of the recursion is bounded by `3K·4.5^L·R²·|α|`, which, in units of the common dyadic grid `g`, must not exceed `2^52`.
*
* @private
* @param {NonNegativeInteger} K - inner dimension
* @param {NonNegativeInteger} L - number of recursion levels
* @param {number} alpha - scalar constant
* @param {number} grid - common dyadic grid
* @returns {NonNegativeInteger} magnitude
*/
function magnitudeAB( K, L, alpha, grid ) {
	var r = HALF_BUDGET / ( 3.0 * max( K, 1 ) * pow( 4.5, L ) * max( abs( alpha )/grid, 1.0 ) );
	return min( floor( sqrt( r ) ), MAX_MAGNITUDE );
}

/**
* Returns the largest integer magnitude for the entries of `C` such that `β*C` is exact and uses at most half of the budget.
*
* @private
* @param {number} beta - scalar constant
* @param {number} grid - common dyadic grid
* @returns {NonNegativeInteger} magnitude
*/
function magnitudeC( beta, grid ) {
	return floor( HALF_BUDGET / max( abs( beta )/grid, 1.0 ) );
}

/**
* Returns randomized layout options.
*
* @private
* @param {Function} randi - PRNG for integers
* @param {(string|null)} order - fixed storage layout for the BLAS interface (offset zero and positive strides), or `null` for a random layout
* @returns {Object} options
*/
function randomLayout( randi, order ) {
	if ( order ) {
		return {
			'order': order,
			'pad': randi( 0, 3 ),
			'offset': 0,
			'tail': randi( 0, 3 ),
			'flip1': false,
			'flip2': false
		};
	}
	return {
		'order': ORDERS[ randi( 0, 1 ) ],
		'pad': randi( 0, 3 ),
		'offset': randi( 0, 5 ),
		'tail': randi( 0, 3 ),
		'flip1': ( randi( 0, 3 ) === 0 ),
		'flip2': ( randi( 0, 3 ) === 0 )
	};
}

/**
* Returns a strided matrix whose buffer elements (including padding) are random integers in `[-R,R]` (zeros are randomly signed).
*
* @private
* @param {Function} randi - PRNG for integers
* @param {NonNegativeInteger} rows - number of rows
* @param {NonNegativeInteger} cols - number of columns
* @param {(number|null)} R - magnitude (`null` fills the buffer with `NaN`)
* @param {(string|null)} order - storage layout (see `randomLayout`)
* @returns {Object} matrix description
*/
function randomMatrix( randi, rows, cols, R, order ) {
	return createMatrix( rows, cols, randomLayout( randi, order ), value );

	function value() {
		var v;
		if ( R === null ) {
			return NaN;
		}
		v = randi( -R, R );
		if ( v === 0 && randi( 0, 1 ) === 1 ) {
			return -0.0;
		}
		return v;
	}
}

/**
* Returns a random problem `C = α*op(A)*op(B) + β*C` with integer data satisfying the exactness bound.
*
* @private
* @param {Function} randi - PRNG for integers
* @param {NonNegativeInteger} M - number of rows in `op(A)` and `C`
* @param {NonNegativeInteger} N - number of columns in `op(B)` and `C`
* @param {NonNegativeInteger} K - inner dimension
* @param {Object} opts - options
* @param {(PositiveInteger|null)} opts.cutoff - recursion cutoff (`null` for a random cutoff)
* @param {(NonNegativeInteger|null)} opts.levels - maximum number of recursion levels (`null` for a random value)
* @param {NumericArray} opts.alphas - candidate values for `α`
* @param {(string|null)} opts.order - storage layout for the BLAS interface, or `null`
* @returns {Object} problem
*/
function randomProblem( randi, M, N, K, opts ) {
	var grid;
	var ra;
	var rb;
	var rc;
	var p;
	var L;

	p = {
		'transA': TRANS[ randi( 0, 1 ) ],
		'transB': TRANS[ randi( 0, 1 ) ],
		'M': M,
		'N': N,
		'K': K,
		'alpha': opts.alphas[ randi( 0, opts.alphas.length-1 ) ],
		'beta': BETAS[ randi( 0, BETAS.length-1 ) ],
		'cutoff': ( opts.cutoff === null ) ? CUTOFFS[ randi( 0, CUTOFFS.length-1 ) ] : opts.cutoff,
		'levels': ( opts.levels === null ) ? LEVELS[ randi( 0, LEVELS.length-1 ) ] : opts.levels,
		'order': opts.order
	};
	L = depth( M, N, K, p.cutoff, p.levels );
	grid = ( p.alpha === 0.5 || p.beta === 0.5 ) ? 0.5 : 1.0;

	// Randomly select small entries (frequent zeros and cancellation) or entries at the exactness bound:
	ra = ( randi( 0, 1 ) === 0 ) ? 6 : magnitudeAB( K, L, p.alpha, grid );
	rb = ( randi( 0, 1 ) === 0 ) ? 6 : magnitudeAB( K, L, p.alpha, grid );
	rc = ( randi( 0, 1 ) === 0 ) ? 6 : magnitudeC( p.beta, grid );
	p.A = ( p.transA === 'no-transpose' ) ? randomMatrix( randi, M, K, ra, p.order ) : randomMatrix( randi, K, M, ra, p.order );
	p.B = ( p.transB === 'no-transpose' ) ? randomMatrix( randi, K, N, rb, p.order ) : randomMatrix( randi, N, K, rb, p.order );

	// When `β = 0`, `C` must not be read, so fill every element (including padding) with `NaN`:
	p.C = randomMatrix( randi, M, N, ( p.beta === 0.0 ) ? null : rc, p.order );
	return p;
}

/**
* Returns a string describing a problem.
*
* @private
* @param {Object} p - problem
* @returns {string} description
*/
function describe( p ) {
	return '(' + [ p.transA, p.transB, p.M, p.N, p.K, p.alpha, p.beta, p.cutoff, p.levels ].join( ', ' ) + ')';
}

/**
* Solves a problem using `dgemm` and a provided implementation and compares the entire output buffers.
*
* @private
* @param {Object} p - problem
* @param {Function} impl - implementation
* @returns {string} failure description (empty if the results are identical)
*/
function evaluate( p, impl ) {
	var acopy;
	var bcopy;
	var ref;
	var out;
	var idx;
	var d;

	acopy = new Float64Array( p.A.buf );
	bcopy = new Float64Array( p.B.buf );
	ref = new Float64Array( p.C.buf );
	out = new Float64Array( p.C.buf );
	if ( p.order ) {
		dgemm( p.order, p.transA, p.transB, p.M, p.N, p.K, p.alpha, p.A.buf, ld( p.A, p.order ), p.B.buf, ld( p.B, p.order ), p.beta, ref, ld( p.C, p.order ) );
	} else {
		dgemm.ndarray( p.transA, p.transB, p.M, p.N, p.K, p.alpha, p.A.buf, p.A.s1, p.A.s2, p.A.o, p.B.buf, p.B.s1, p.B.s2, p.B.o, p.beta, ref, p.C.s1, p.C.s2, p.C.o );
	}
	if ( impl( p, out ) !== out ) {
		return 'does not return the output matrix';
	}
	// Compare with `Object.is` semantics when `β = 0` (signed zeros must agree); otherwise, signed zeros may differ:
	d = firstDifference( ref, out, p.beta === 0.0 );
	if ( d >= 0 ) {
		return 'C differs from `dgemm` at buffer index ' + d + ' (expected ' + ref[ d ] + ', actual ' + out[ d ] + ')';
	}
	for ( idx = 0; idx < out.length; idx++ ) {
		if ( p.C.mask[ idx ] === 0 && !isSameValue( out[ idx ], p.C.buf[ idx ] ) ) {
			return 'padding element ' + idx + ' of C was modified';
		}
	}
	if ( firstDifference( acopy, p.A.buf, true ) >= 0 ) {
		return 'A was modified';
	}
	if ( firstDifference( bcopy, p.B.buf, true ) >= 0 ) {
		return 'B was modified';
	}
	return '';
}

/**
* Returns the leading dimension of a strided matrix stored using a specified layout.
*
* @private
* @param {Object} x - matrix description
* @param {string} order - storage layout
* @returns {PositiveInteger} leading dimension
*/
function ld( x, order ) {
	return ( order === 'row-major' ) ? x.s1 : x.s2;
}

/**
* Solves a problem using `base.js` with explicit cutoff and levels.
*
* @private
* @param {Object} p - problem
* @param {Float64Array} out - output buffer
* @returns {Float64Array} output buffer
*/
function viaBase( p, out ) {
	return base( p.transA, p.transB, p.M, p.N, p.K, p.alpha, p.A.buf, p.A.s1, p.A.s2, p.A.o, p.B.buf, p.B.s1, p.B.s2, p.B.o, p.beta, out, p.C.s1, p.C.s2, p.C.o, p.cutoff, p.levels );
}

/**
* Solves a problem using the public ndarray interface.
*
* @private
* @param {Object} p - problem
* @param {Float64Array} out - output buffer
* @returns {Float64Array} output buffer
*/
function viaNdarray( p, out ) {
	return ndarray( p.transA, p.transB, p.M, p.N, p.K, p.alpha, p.A.buf, p.A.s1, p.A.s2, p.A.o, p.B.buf, p.B.s1, p.B.s2, p.B.o, p.beta, out, p.C.s1, p.C.s2, p.C.o );
}

/**
* Solves a problem using the public BLAS interface.
*
* @private
* @param {Object} p - problem
* @param {Float64Array} out - output buffer
* @returns {Float64Array} output buffer
*/
function viaBLAS( p, out ) {
	return blas( p.order, p.transA, p.transB, p.M, p.N, p.K, p.alpha, p.A.buf, ld( p.A, p.order ), p.B.buf, ld( p.B, p.order ), p.beta, out, ld( p.C, p.order ) );
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof base, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns results identical to `dgemm` (2000 seeded trials: random dimensions, cutoffs, levels, transpose operations, layouts, padding, offsets, negative strides, α, and β; entire buffers)', function test( t ) {
	var mismatches;
	var recursive;
	var failures;
	var expected;
	var randi;
	var opts;
	var msg;
	var p;
	var i;

	randi = discreteUniform.factory({
		'seed': SEED
	});
	opts = {
		'cutoff': null,
		'levels': null,
		'alphas': ALPHAS,
		'order': null
	};
	failures = 0;
	mismatches = 0;
	recursive = 0;
	for ( i = 0; i < TRIALS; i++ ) {
		p = randomProblem( randi, randi( 0, MAX_DIM ), randi( 0, MAX_DIM ), randi( 0, MAX_DIM ), opts );
		ncalls = 0;
		msg = evaluate( p, viaBase );
		if ( msg ) {
			failures += 1;
			if ( failures <= 5 ) {
				t.fail( 'trial ' + i + ': ' + msg + ' ' + describe( p ) );
			}
		}
		if ( ncalls > 0 ) {
			recursive += 1;
		}
		// Integer data within the exactness bound never trips the overflow guards, so the recursive path must be taken whenever the problem recurses and `α` is nonzero:
		expected = ( depth( p.M, p.N, p.K, p.cutoff, p.levels ) > 0 && p.alpha !== 0.0 );
		if ( expected !== ( ncalls > 0 ) ) {
			mismatches += 1;
		}
	}
	t.strictEqual( failures, 0, 'returns expected value (' + TRIALS + ' trials)' );
	t.strictEqual( mismatches, 0, 'takes the recursive path if and only if the problem recurses and α is nonzero' );
	t.ok( recursive > TRIALS/2, 'took the recursive path in ' + recursive + ' of ' + TRIALS + ' trials (' + ( ( 100*recursive )/TRIALS ).toFixed( 1 ) + '%)' );
	t.end();
});

tape( 'the function returns results identical to `dgemm` for large rectangular problems', function test( t ) {
	var configs;
	var shapes;
	var randi;
	var msg;
	var cfg;
	var p;
	var s;
	var i;
	var j;
	var k;

	shapes = [
		[ 300, 3, 300 ],
		[ 3, 300, 300 ],
		[ 300, 300, 3 ],
		[ 257, 129, 65 ],
		[ 65, 257, 129 ]
	];
	configs = [
		[ 1, 100 ],
		[ 2, 2 ],
		[ 8, 100 ]
	];
	randi = discreteUniform.factory({
		'seed': SEED+1
	});
	for ( i = 0; i < shapes.length; i++ ) {
		s = shapes[ i ];
		for ( j = 0; j < configs.length; j++ ) {
			for ( k = 0; k < 2; k++ ) {
				cfg = {
					'cutoff': configs[ j ][ 0 ],
					'levels': configs[ j ][ 1 ],
					'alphas': NONZERO_ALPHAS,
					'order': null
				};
				p = randomProblem( randi, s[ 0 ], s[ 1 ], s[ 2 ], cfg );
				ncalls = 0;
				msg = evaluate( p, viaBase );
				t.strictEqual( msg, '', 'returns expected value ' + describe( p ) );
				t.strictEqual( ncalls > 0, depth( p.M, p.N, p.K, p.cutoff, p.levels ) > 0, 'takes the expected path ' + describe( p ) );
			}
		}
	}
	t.end();
});

tape( 'the public interfaces return results identical to `dgemm` (default cutoff and levels; recursing and non-recursing sizes)', function test( t ) {
	var shapes;
	var counts;
	var randi;
	var opts;
	var msg;
	var c;
	var p;
	var s;
	var i;
	var j;

	// Shapes relative to the default cutoff `c`: two thin shapes, three shapes which recurse (odd and even dimensions), and a boundary shape having one dimension equal to `c` (non-recursing):
	c = defaults.CUTOFF;
	shapes = [
		[ 300, 3, 300 ],
		[ 3, 300, 300 ],
		[ (4*c)+1, (2*c)+1, c+1 ],
		[ c+1, c+1, c+1 ],
		[ (2*c)+1, c+2, floor( (3*c)/2 )+1 ],
		[ c, (3*c)+8, (2*c)+2 ]
	];
	randi = discreteUniform.factory({
		'seed': SEED+2
	});
	counts = [ 0, 0 ]; // [ non-recursive, recursive ]
	for ( i = 0; i < shapes.length; i++ ) {
		s = shapes[ i ];
		opts = {
			'cutoff': c,
			'levels': defaults.LEVELS,
			'alphas': NONZERO_ALPHAS,
			'order': null
		};
		for ( j = 0; j < 2; j++ ) {
			opts.order = ( j === 0 ) ? null : ORDERS[ i%2 ];
			p = randomProblem( randi, s[ 0 ], s[ 1 ], s[ 2 ], opts );
			ncalls = 0;
			msg = evaluate( p, ( j === 0 ) ? viaNdarray : viaBLAS );
			t.strictEqual( msg, '', ( ( j === 0 ) ? 'ndarray' : 'BLAS (' + p.order + ')' ) + ' interface returns expected value ' + describe( p ) );

			// Integer data within the exactness bound never trips the overflow guards, so the recursive path must be taken if and only if the problem recurses:
			t.strictEqual( ncalls > 0, depth( p.M, p.N, p.K, c, defaults.LEVELS ) > 0, 'takes the expected path ' + describe( p ) );
			counts[ ( ncalls > 0 ) ? 1 : 0 ] += 1;
		}
	}
	t.strictEqual( counts[ 1 ], 6, 'takes the recursive path for three shapes (both interfaces)' );
	t.strictEqual( counts[ 0 ], 6, 'delegates to `dgemm` for three shapes (both interfaces)' );
	t.end();
});
